/** The app version from package.json, injected by vite.config.ts. */
declare const __APP_VERSION__: string;

/** The text of the repository's LICENSE (MIT), injected by vite.config.ts. */
declare const __APP_LICENSE__: string;

/** Generated by scripts/generate-licenses.mjs; typed by hand, not inferred from 260 KB of JSON. */
declare module "*/third-party-licenses.json" {
  const data: import("./lib/thirdParty").ThirdPartyLicenses;
  export default data;
}
